package checker

import (
	crypto "crypto/sha256"
	"encoding/hex"
	fs "io/fs"
	"sort"

	"github.com/lizongying/nolang/cache"
)

// Embedded std tables.
//
// stdsig_gen.go (generated by genstdsig) bakes SIX signature tables
// (funcSigs + funcParams merged into embeddedStdFuncSigs, methodSigs +
// methodParams merged into embeddedStdMethodSigs, plus structFields / aliases
// / structMod / enumVariants) + the module list (embeddedStdModules) + the
// content key into the binary as Go source literals, so every `no build` skips
// PASS1 signature collection entirely.
//
// Validation: at build time the Makefile runs the SAME independent genstdsig
// tool over the current on-disk src/std and injects its hash into the binary
// via -X as checker.StdSigKey. At runtime StdSigKey is compared directly
// against embeddedStdSigKey (also derived from src/std by genstdsig). Because
// both are computed independently from src/std, a stale stdsig_gen.go is
// actually caught. There is NO runtime re-hash and NO fallback: if StdSigKey
// is empty (binary not built via `make`) or mismatches embeddedStdSigKey,
// CollectStdModuleSignatures hard-fails and tells the developer to run
// `make no` (never `cd src && go build`, never bare `go test`).
//
// The full-collection fallback from the embedded StdFS is only taken when
// stdsig_gen.go is entirely absent (e.g. before the first `make gen`); in
// normal builds the table is always present and fresh.

// StdSigEntry holds both the declared PARAMETER types and the RESULT (return)
// types for one std function or method. Merging the old *Sigs (results) and
// *Params tables into one entry lets the generator emit a single table and the
// checker read params/results from one place (see funcargs.go stdMethodParamTypes).
type StdSigEntry struct {
	Params  []string
	Results []string
}

// ---- embedded signature table variables (populated by stdsig_gen.go) ----
//
// When stdsig_gen.go is present (generated by genstdsig), its init() sets
// embeddedStdSigKey (derived from src/std) and fills the six signature tables.
// When stdsig_gen.go is NOT yet generated, embeddedStdSigKey stays empty
// and CollectStdModuleSignatures falls back to full collection.
var (
	embeddedStdSigKey        = ""
	// StdSigKey is injected at build time via -X (Makefile LD_FLAGS_WITH_SIG ->
	// github.com/lizongying/nolang/checker.StdSigKey). The Makefile derives it
	// from the CURRENT src/std via the independent genstdsig tool, so it carries
	// the same hash as embeddedStdSigKey. The runtime compares the two directly
	// to validate the baked table WITHOUT re-hashing every std source file.
	// Empty means the binary was NOT built via `make` (e.g. `cd src && go build`
	// or bare `go test`) — CollectStdModuleSignatures then hard-fails and
	// requires `make no`; there is deliberately NO computeStdSigKey fallback.
	StdSigKey                = ""
	// embeddedStdFuncSigs merges the old funcSigs (RESULT types) and
	// funcParams (PARAMETER types) tables into one map keyed by "module.fn"
	// or the bare fn name. embeddedStdMethodSigs does the same for struct
	// methods, keyed by "module.struct.method". Collapsing the four tables
	// into two entry tables keeps generation and the checker's argument-type
	// lookup in one place (see funcargs.go stdMethodParamTypes).
	embeddedStdFuncSigs    = map[string]StdSigEntry{}
	embeddedStdMethodSigs = map[string]StdSigEntry{}
	embeddedStdStructFields  = map[string]map[string]string{}
	embeddedStdAliases       = map[string]string{}
	embeddedStdStructMod     = map[string]string{}
	embeddedStdEnumVariants = map[string][]string{}
	// embeddedStdModules is the baked module KV map (ShortName -> FullPath), the
	// compact successor to the old []StdModuleInfo slice. ShortName is unique
	// across std modules (genstdsig hard-fails on a collision), so it is a safe
	// map key. KnownStdModules / GetStdModules return this map directly (no
	// slice materialization); it is validated by embeddedStdSigKey against the
	// injected StdSigKey — the SAME key as the other 6 signature tables, since
	// genstdsig derives both from the same src/std.
	embeddedStdModules      = map[string]string{}
)

// ComputeStdSigKeyFromFS is the exported, FS-parameterised variant used by
// the signature-table generator (genstdsig) to compute the key from the
// on-disk src/ tree, and by genstdsig's `-key-only` mode to emit the key the
// Makefile injects via -X. It is the single source of truth for the std
// content hash; both embeddedStdSigKey and the injected StdSigKey derive from
// it, which is what makes the runtime compare meaningful.
func ComputeStdSigKeyFromFS(fsys fs.FS) (string, error) {
	return computeStdSigKeyFromFS(fsys)
}

func computeStdSigKeyFromFS(fsys fs.FS) (string, error) {
	known := ListStdModules(fsys)
	sorted := append([]StdModuleInfo(nil), known...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].FullPath < sorted[j].FullPath })

	h := crypto.New()
	for _, info := range sorted {
		embedPath := "std/" + info.FullPath + ".no"
		source, err := fs.ReadFile(fsys, embedPath)
		if err != nil {
			return "", err
		}
		h.Write([]byte(info.FullPath))
		h.Write([]byte{0})
		h.Write([]byte(cache.ContentKey(string(source))))
		h.Write([]byte{0})
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

